// Generates the Phase 6 performance fixtures (docs/specs/performance.md §2).
//
// These are deliberately not generated by CI or by a test run: the largest take
// hours and tens of gigabytes, so building them is an explicit act by whoever
// owns the machine. The harness reuses a fixture whose parameters already match
// (P6-02), so re-running this script after the first build is cheap.
//
//   node scripts/generate-fixtures.mjs --list
//   node scripts/generate-fixtures.mjs --only wt-huge
//   node scripts/generate-fixtures.mjs --only wt-huge --files 300000
//   node scripts/generate-fixtures.mjs --dry-run
//
// Results are written under target/fjord-bench/<name>/ and a JSON record per
// run under target/fjord-bench/results/.

import { spawn } from "node:child_process";
import { mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const RESULTS_DIR = join(ROOT, "target", "fjord-bench", "results");

/**
 * `files` is the count the fixture is generated with; `variants` lists the
 * other sizes the spec calls for, selectable with --files.
 *
 * Sizes are file counts rather than byte estimates, because the byte cost is
 * dominated by the filesystem's per-file overhead and differs enough between
 * NTFS, APFS, and ext4 that a single number would be misleading. The first run
 * prints its own elapsed time; that is the number to trust for your machine.
 */
const FIXTURES = [
  {
    name: "wt-huge",
    slo: "SLO-6",
    summary: "Wide working tree, shallow history — what makes `status` expensive.",
    files: 150_000,
    variants: [150_000, 300_000],
    approxFiles: (files) => files,
  },
  {
    name: "wt-noisy",
    slo: "SLO-7, SLO-11",
    summary:
      "Tracked files plus 200k ignored and 20k untracked — the cost a tracked-file count never predicts.",
    files: 50_000,
    variants: [50_000],
    approxFiles: (files) => files + 220_000,
  },
  {
    name: "hist-deep",
    slo: "SLO-8",
    summary:
      "Deep history over a narrow tree, with the commit-graph a repository this size always has.",
    sizeFlag: "--commits",
    commits: 500_000,
    variants: [500_000, 1_000_000],
    approxFiles: () => 50,
    needsGit: true,
  },
  {
    name: "refs-many",
    slo: "SLO-16",
    summary: "5k branches, 5k tags, 20 remotes, packed the way a real repository keeps them.",
    sizeFlag: "--commits",
    commits: 2_000,
    variants: [2_000],
    approxFiles: () => 20,
    needsGit: true,
  },
  {
    name: "diff-giant",
    slo: "SLO-9, SLO-10",
    summary:
      "A 50 MB text file, a 500k-line file, and a binary blob — three ways a diff view breaks.",
    sizeFlag: null,
    approxFiles: () => 3,
    approxDisk: "~115 MB",
  },
  {
    name: "ws-100",
    slo: "SLO-3, SLO-13, SLO-14, SLO-15",
    summary: "100 repositories under one root — the workspace shape, where count is the cost.",
    sizeFlag: "--workspace-repos",
    workspaceRepos: 100,
    variants: [100],
    approxFiles: (repos) => repos * 50,
    slowest: true,
  },
];

/**
 * The size a fixture is generated at, and the flag that overrides it.
 * `sizeFlag: null` means the fixture has one fixed shape.
 */
function sizeOf(fixture, options) {
  if (fixture.sizeFlag === null) return { flag: null, value: null };
  const flag = fixture.sizeFlag ?? "--files";
  const fallback = {
    "--files": fixture.files,
    "--commits": fixture.commits,
    "--workspace-repos": fixture.workspaceRepos,
  }[flag];
  const override = {
    "--files": options.files,
    "--commits": options.commits,
    "--workspace-repos": options.workspaceRepos,
  }[flag];
  return { flag, value: override ?? fallback };
}

function parseArgs(argv) {
  const options = {
    only: null,
    files: null,
    commits: null,
    workspaceRepos: null,
    force: false,
    dryRun: false,
    list: false,
  };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = () => {
      const value = argv[index + 1];
      if (value === undefined) throw new Error(`${arg} requires a value`);
      index += 1;
      return value;
    };
    switch (arg) {
      case "--only":
        options.only = next().split(",").map((name) => name.trim());
        break;
      case "--files":
        options.files = Number.parseInt(next(), 10);
        if (!Number.isFinite(options.files) || options.files <= 0) {
          throw new Error("--files must be a positive integer");
        }
        break;
      case "--commits":
        options.commits = Number.parseInt(next(), 10);
        if (!Number.isFinite(options.commits) || options.commits <= 0) {
          throw new Error("--commits must be a positive integer");
        }
        break;
      case "--workspace-repos":
        options.workspaceRepos = Number.parseInt(next(), 10);
        if (!Number.isFinite(options.workspaceRepos) || options.workspaceRepos <= 0) {
          throw new Error("--workspace-repos must be a positive integer");
        }
        break;
      case "--force":
        options.force = true;
        break;
      case "--dry-run":
        options.dryRun = true;
        break;
      case "--list":
        options.list = true;
        break;
      case "--help":
      case "-h":
        options.list = true;
        break;
      default:
        throw new Error(`unknown argument: ${arg}`);
    }
  }
  return options;
}

function selected(options) {
  if (!options.only) return FIXTURES;
  const chosen = FIXTURES.filter((fixture) => options.only.includes(fixture.name));
  const unknown = options.only.filter(
    (name) => !FIXTURES.some((fixture) => fixture.name === name),
  );
  if (unknown.length > 0) {
    throw new Error(
      `unknown fixture(s): ${unknown.join(", ")}. Available: ${FIXTURES.map((f) => f.name).join(", ")}`,
    );
  }
  return chosen;
}

function commandFor(fixture, options) {
  const { flag, value } = sizeOf(fixture, options);
  const args = ["run", "--release", "-p", "fjord-bench", "--", "--fixture", fixture.name];
  if (flag !== null) args.push(flag, String(value));
  args.push("--json", join(RESULTS_DIR, `${fixture.name}${value === null ? "" : `-${value}`}.json`));
  if (options.force) args.push("--force");
  return args;
}

const SIZE_LABEL = {
  "--files": "tracked files",
  "--commits": "commits",
  "--workspace-repos": "repositories",
};

function describe(fixture, options) {
  const { flag, value } = sizeOf(fixture, options);
  const lines = [`  ${fixture.name}  [${fixture.slo}]`, `    ${fixture.summary}`];

  if (flag !== null) {
    const variants =
      fixture.variants.length > 1
        ? ` (variants: ${fixture.variants.map((size) => size.toLocaleString("en-US")).join(", ")})`
        : "";
    lines.push(`    ${SIZE_LABEL[flag]}: ${value.toLocaleString("en-US")}${variants}`);
  }
  lines.push(
    `    files on disk: ~${fixture.approxFiles(value ?? 0).toLocaleString("en-US")}` +
      (fixture.approxDisk ? ` (${fixture.approxDisk})` : ""),
  );
  if (fixture.needsGit) {
    lines.push("    requires: git on PATH (commit-graph, packed refs)");
  }
  if (fixture.slowest) {
    lines.push("    note: the longest build here — one repository's history, a hundred times");
  }
  return lines.join("\n");
}

function run(args) {
  return new Promise((resolve, reject) => {
    const child = spawn("cargo", args, { cwd: ROOT, stdio: "inherit", shell: process.platform === "win32" });
    child.on("error", reject);
    child.on("exit", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`cargo exited with code ${code}`));
    });
  });
}

function formatDuration(ms) {
  const seconds = Math.round(ms / 1000);
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ${seconds % 60}s`;
}

async function main() {
  let options;
  try {
    options = parseArgs(process.argv.slice(2));
  } catch (error) {
    console.error(`${error.message}\n`);
    console.error("Run with --list to see the available fixtures.");
    process.exit(1);
  }

  if (options.list) {
    console.log("Phase 6 performance fixtures (docs/specs/performance.md §2):\n");
    for (const fixture of FIXTURES) console.log(describe(fixture, options), "\n");
    console.log("Generated under target/fjord-bench/<name>/, reused when parameters match.");
    console.log("Re-run with --force to rebuild a fixture that already matches.");
    return;
  }

  const fixtures = selected(options);
  mkdirSync(RESULTS_DIR, { recursive: true });

  console.log(`Generating ${fixtures.length} fixture(s). This is slow by design.\n`);
  for (const fixture of fixtures) {
    console.log(describe(fixture, options));
  }
  console.log("");

  if (options.dryRun) {
    for (const fixture of fixtures) {
      console.log(`cargo ${commandFor(fixture, options).join(" ")}`);
    }
    return;
  }

  const started = Date.now();
  for (const fixture of fixtures) {
    const fixtureStarted = Date.now();
    console.log(`=== ${fixture.name} ===`);
    await run(commandFor(fixture, options));
    console.log(`--- ${fixture.name} finished in ${formatDuration(Date.now() - fixtureStarted)}\n`);
  }
  console.log(`All fixtures ready in ${formatDuration(Date.now() - started)}.`);
  console.log(`Records written to ${RESULTS_DIR}`);
}

main().catch((error) => {
  console.error(`\nfixture generation failed: ${error.message}`);
  process.exit(1);
});
